def choose_move(observation):
    x, y = observation['self_position']
    res = observation.get('resources', [])
    opp = observation.get('opponent_position', [])
    obstacles = set(observation.get('obstacles', []))
    width = observation['grid_width']
    height = observation['grid_height']

    def safe_move(dx, dy):
        nx, ny = x + dx, y + dy
        if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
            return True
        return False

    def move_towards(tx, ty):
        dx = (tx > x) - (tx < x)
        dy = (ty > y) - (ty < y)
        if safe_move(dx, dy):
            return [dx, dy]
        # try horizontal
        if dx != 0 and safe_move(dx, 0):
            return [dx, 0]
        # try vertical
        if dy != 0 and safe_move(0, dy):
            return [0, dy]
        # try no move
        if safe_move(0, 0):
            return [0, 0]
        # fallback: neutral move
        return [0, 0]

    if res:
        rx, ry = res[0]
        move = move_towards(rx, ry)
        return move

    if opp:
        ox, oy = opp
        # move away from opponent
        dx = (x > ox) - (x < ox)
        dy = (y > oy) - (y < oy)
        if safe_move(dx, dy):
            return [dx, dy]
        # try alternatives
        for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
            if safe_move(ddx, ddy):
                return [ddx, ddy]
        return [0, 0]

    # else, move randomly
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1), (0,0)]:
        if safe_move(dx, dy):
            return [dx, dy]
    return [0, 0]
